const rawExtractionId = $input.first().json.extractionId;
const extractionId =
  typeof rawExtractionId === 'string'
    ? rawExtractionId.trim()
    : '';

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!uuidPattern.test(extractionId)) {
  throw new Error(
    'INVALID_EXTRACTION_ID: extractionId must be a valid UUID.'
  );
}

return [
  {
    json: {
      extractionId,
    },
  },
];

const resolved = $input.first().json;

if (resolved.resolutionStatus !== 'RESOLVED') {
  throw new Error(
    `UNEXPECTED_RESOLUTION_STATUS: ${resolved.resolutionStatus}`
  );
}

const profile =
  resolved.profile &&
  typeof resolved.profile === 'object' &&
  !Array.isArray(resolved.profile)
    ? resolved.profile
    : {};

const resumeDimensionAssessments = Array.isArray(
  resolved.resumeDimensionAssessments
)
  ? resolved.resumeDimensionAssessments
  : [];

const grades = Array.isArray(resolved.grades)
  ? resolved.grades
  : [];

const resumeDimensions = resumeDimensionAssessments.map(
  (assessment) => ({
    code: assessment.code,
    title: assessment.title,
    weight: Number(assessment.weight),
    effectiveScore: Number(assessment.effectiveScore),
    confidence: assessment.confidence,
  })
);

return [
  {
    json: {
      extraction: {
        id: resolved.extractionId,
        positionCode: resolved.positionCode,
        targetGradeCode: resolved.targetGradeCode,
        sourceFileName: resolved.sourceFileName,
        jobDescription: resolved.jobDescription,
      },

      candidate: {
        fullName:
          String(profile.candidate?.fullName ?? '').trim() ||
          'Unknown candidate',
      },

      candidateProfile: profile,

      gradeGuide: {
        id: resolved.gradeGuideId,
        version: resolved.gradeGuideVersion,
        schemaVersion: resolved.gradeGuideSchemaVersion,
        targetGrade: resolved.gradeDefinition,
        grades,
        dimensions: resolved.dimensions,
        scoringScale: resolved.scoringScale,
      },

      resumeGrade: {
        assessmentId: resolved.resumeAssessmentId,
        decision: resolved.resumeDecision,
        overallScore: Number(resolved.resumeOverallScore),
        minimumOverallScore: Number(resolved.resumeMinimumOverallScore),
        thresholdMet: resolved.resumeThresholdMet === true,
        mandatoryDimensionsMet:
          resolved.resumeMandatoryDimensionsMet === true,
        assessedAt: resolved.resumeAssessedAt,
        summary: resolved.resumeAssessmentSummary,
        dimensions: resumeDimensions,
      },
    },
  },
];

const interviewConfiguration = {
  schemaVersion: '1.0',

  rounds: {
    first: {
      totalQuestions: 20,
      singleChoice: 6,
      multiChoice: 6,
      explanatory: 8,
    },

    followUp: {
      totalQuestions: 10,
      singleChoice: 3,
      multiChoice: 3,
      explanatory: 4,
    },
  },
};

return [
  {
    json: interviewConfiguration,
  },
];

