const chainResult = $input.first().json;

let questionPlan =
  chainResult.output ??
  chainResult.text ??
  chainResult.response ??
  chainResult;

if (
  questionPlan &&
  typeof questionPlan === 'object' &&
  questionPlan.output &&
  !questionPlan.questions
) {
  questionPlan = questionPlan.output;
}

if (typeof questionPlan === 'string') {
  try {
    questionPlan = JSON.parse(questionPlan);
  } catch (error) {
    throw new Error(
      `INVALID_INTERVIEW_PLAN_JSON: ${error.message}`
    );
  }
}

const promptContext =
  $('Build Interview Question Prompt').first().json;

const interviewContext =
  promptContext.interviewContext;

const roundConfig =
  promptContext.config.rounds.first;

const expected = {
  total: Number(roundConfig.totalQuestions),
  single_choice: Number(roundConfig.singleChoice),
  multi_choice: Number(roundConfig.multiChoice),
  explanatory: Number(roundConfig.explanatory),
};

const configErrors = [];

if (
  !Number.isInteger(expected.total) ||
  expected.total < 1 ||
  expected.total > 20
) {
  configErrors.push('totalQuestions must be an integer from 1 to 20');
}

for (const type of ['single_choice', 'multi_choice', 'explanatory']) {
  if (!Number.isInteger(expected[type]) || expected[type] < 0) {
    configErrors.push(`${type} count must be a non-negative integer`);
  }
}

if (
  expected.single_choice +
    expected.multi_choice +
    expected.explanatory !==
  expected.total
) {
  configErrors.push('question type counts must add up to totalQuestions');
}

if (configErrors.length > 0) {
  throw new Error(
    `INVALID_INTERVIEW_CONFIGURATION: ${configErrors.join("; ")}`
  );
}

const dimensions =
  interviewContext.gradeGuide.dimensions;

const dimensionCodes = dimensions.map(
  (dimension) => dimension.code
);

const errors = [];

if (
  !questionPlan ||
  typeof questionPlan !== 'object' ||
  Array.isArray(questionPlan)
) {
  errors.push('question plan must be an object');
}

const questions = Array.isArray(questionPlan?.questions)
  ? questionPlan.questions
  : [];

if (questions.length !== expected.total) {
  errors.push(
    `expected exactly ${expected.total} questions, received ${questions.length}`
  );
}

const sanitizedQuestions = [];
const usedIds = new Set();
const typeCounts = {
  single_choice: 0,
  multi_choice: 0,
  explanatory: 0,
};
const dimensionCounts = {};

for (const [index, question] of questions.entries()) {
  const questionNumber = index + 1;

  const rawId = String(question?.id ?? '').trim();
  const id =
    rawId.replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 40) ||
    `Q${questionNumber}`;

  if (usedIds.has(id)) {
    errors.push(`duplicate question id: ${id}`);
    continue;
  }

  usedIds.add(id);

  const dimensionCode = String(question?.dimensionCode ?? '').trim();

  if (!dimensionCodes.includes(dimensionCode)) {
    errors.push(
      `${id}: unknown dimensionCode ${dimensionCode || 'empty'}`
    );
    continue;
  }

  const type = String(question?.type ?? '').trim();

  if (!(type in typeCounts)) {
    errors.push(
      `${id}: type must be single_choice, multi_choice or explanatory`
    );
    continue;
  }

  const questionText = String(question?.questionText ?? '').trim();

  if (questionText.length < 10) {
    errors.push(`${id}: questionText is too short`);
    continue;
  }

  typeCounts[type] += 1;

  dimensionCounts[dimensionCode] =
    (dimensionCounts[dimensionCode] ?? 0) + 1;

  const rawOptions = Array.isArray(question?.options)
    ? question.options
    : [];

  if (type === 'explanatory') {
    if (rawOptions.length > 0) {
      errors.push(
        `${id}: explanatory questions must not define options`
      );
      continue;
    }

    sanitizedQuestions.push({
      id,
      dimensionCode,
      type,
      questionText,
      options: [],
    });

    continue;
  }

  const minimumOptions = type === 'single_choice' ? 3 : 4;
  const maximumOptions = type === 'single_choice' ? 4 : 6;

  if (
    rawOptions.length < minimumOptions ||
    rawOptions.length > maximumOptions
  ) {
    errors.push(
      `${id}: ${type} requires ${minimumOptions} to ${maximumOptions} options`
    );
    continue;
  }

  const labels = new Set();
  const options = [];

  for (const option of rawOptions) {
    const label = String(option?.label ?? '').trim();

    if (!label) {
      errors.push(`${id}: option label is empty`);
      continue;
    }

    if (labels.has(label)) {
      errors.push(`${id}: duplicate option label`);
      continue;
    }

    labels.add(label);

    const score = Number(option?.score);

    if (!Number.isInteger(score) || score < 0 || score > 4) {
      errors.push(
        `${id}: option scores must be integers from 0 to 4`
      );
      continue;
    }

    options.push({ label, score });
  }

  if (options.length !== rawOptions.length) {
    continue;
  }

  const distinctScores = new Set(
    options.map((option) => option.score)
  );

  if (distinctScores.size < 2) {
    errors.push(
      `${id}: options must contain at least two distinct scores`
    );
    continue;
  }

  sanitizedQuestions.push({
    id,
    dimensionCode,
    type,
    questionText,
    options,
  });
}

if (sanitizedQuestions.length !== expected.total) {
  errors.push(
    `only ${sanitizedQuestions.length} of ${expected.total} questions survived validation`
  );
}

for (const type of Object.keys(typeCounts)) {
  if (typeCounts[type] !== expected[type]) {
    errors.push(
      `expected exactly ${expected[type]} ${type} questions, received ${typeCounts[type]}`
    );
  }
}

for (const dimensionCode of dimensionCodes) {
  const count = dimensionCounts[dimensionCode] ?? 0;

  if (count < 2 || count > 4) {
    errors.push(
      `${dimensionCode}: received ${count} questions, expected between 2 and 4`
    );
  }
}

if (errors.length > 0) {
  throw new Error(`INVALID_INTERVIEW_PLAN: ${errors.join("; ")}`);
}

const formFields = sanitizedQuestions.map(
  (question, index) => {
    const fieldLabel =
      `${index + 1}. ${question.questionText}`;

    if (question.type === 'explanatory') {
      return {
        fieldLabel,
        fieldName: `q_${question.id}`,
        fieldType: 'textarea',
        placeholder: 'پاسخ خود را همین‌جا بنویسید…',
        requiredField: true,
      };
    }

    return {
      fieldLabel,
      fieldName: `q_${question.id}`,
      fieldType: question.type === 'multi_choice' ? 'checkbox' : 'radio',
      fieldOptions: {
        values: question.options.map(
          (option) => ({ option: option.label })
        ),
      },
      requiredField: true,
    };
  }
);

const candidateName =
  interviewContext.candidate.fullName;

return [
  {
    json: {
      interviewContext,

      questionPlan: {
        schemaVersion: '1.0',
        round: 'first',
        title: String(
          questionPlan.interviewPlanTitle ?? 'TalentAI Technical Interview'
        ).trim(),
        questions: sanitizedQuestions,
        generationWarnings: Array.isArray(
          questionPlan.generationWarnings
        )
          ? questionPlan.generationWarnings.map(String)
          : [],
      },

      formFields,

      interviewFormTitle: 'مصاحبه فنی TalentAI — مرحله اول',

      interviewFormDescription:
        `${candidateName} عزیز، لطفاً به هر ${expected.total} سؤال پاسخ بدهید و سپس فرم را ارسال کنید.` +
        ` این مجموعه شامل ${expected.single_choice} سؤال چندگزینه‌ای تک‌انتخابی، ${expected.multi_choice} سؤال چندگزینه‌ای چندانتخابی و ${expected.explanatory} سؤال تشریحی است.` +
        ' در سؤال‌های چندانتخابی می‌توانید چند گزینه را انتخاب کنید.',
    },
  },
];

const formAnswers = $input.first().json;

const planContext =
  $('Validate Interview Questions').first().json;

const interviewContext =
  planContext.interviewContext;

const questionPlan =
  planContext.questionPlan;

const errors = [];
const answerRecords = [];

const toAnswerList = (value) => {
  if (Array.isArray(value)) {
    return value.map((item) => String(item ?? '').trim()).filter(Boolean);
  }

  const text = String(value ?? '').trim();
  return text ? [text] : [];
};

for (const question of questionPlan.questions) {
  const answerList = toAnswerList(formAnswers[`q_${question.id}`]);

  if (answerList.length === 0) {
    errors.push(`${question.id}: answer is empty`);
    continue;
  }

  if (question.type === 'explanatory') {
    answerRecords.push({
      round: 'first',
      id: question.id,
      dimensionCode: question.dimensionCode,
      type: question.type,
      questionText: question.questionText,
      answerLabels: [],
      answerText: answerList.join('\n'),
      mcqScore: null,
      llmScore: null,
      llmRationale: '',
      finalScore: null,
    });

    continue;
  }

  const unknownOption = answerList.find(
    (label) => !question.options.some((option) => option.label === label)
  );

  if (unknownOption !== undefined) {
    errors.push(
      `${question.id}: submitted option does not match the questionnaire`
    );
    continue;
  }

  if (question.type === 'single_choice' && answerList.length > 1) {
    errors.push(`${question.id}: only one option can be selected`);
    continue;
  }

  const selectedScores = answerList.map(
    (label) =>
      question.options.find((option) => option.label === label).score
  );

  const mcqScore =
    question.type === 'single_choice'
      ? selectedScores[0]
      : Math.round(
          (selectedScores.reduce(
            (total, score) => total + score,
            0
          ) /
            selectedScores.length) *
            100
        ) / 100;

  answerRecords.push({
    round: 'first',
    id: question.id,
    dimensionCode: question.dimensionCode,
    type: question.type,
    questionText: question.questionText,
    answerLabels: answerList,
    answerText: '',
    mcqScore,
    llmScore: null,
    llmRationale: '',
    finalScore: mcqScore,
  });
}

if (errors.length > 0) {
  throw new Error(`INVALID_INTERVIEW_ANSWERS: ${errors.join("; ")}`);
}

return [
  {
    json: {
      interviewContext,
      answerRecords,
    },
  },
];

const roundOneContext = $input.first().json;

const interviewContext =
  roundOneContext.interviewContext;

const answerRecords =
  roundOneContext.answerRecords;

const config =
  $('Interview Configuration').first().json;

const roundConfig = config.rounds.followUp;

const instructions = [
  'You are the interview-designer component of TalentAI.',
  '',
  'Your only responsibility is to design the follow-up round of the candidate interview.',
  'This round must be derived strictly from the answers the candidate gave in the first round.',
  'You must not decide the final grade.',
  'You must not score or evaluate the candidate.',
  'You must not calculate any final score.',
  '',
  'Rules:',
  '1. Produce exactly ' + roundConfig.totalQuestions + ' questions.',
  '2. Produce exactly ' + roundConfig.singleChoice + ' single_choice, ' + roundConfig.multiChoice + ' multi_choice and ' + roundConfig.explanatory + ' explanatory questions.',
  '3. Every question belongs to exactly one dimension from gradeGuide.dimensions, using its exact code.',
  '4. Every dimension must receive at least one question, and no dimension may receive more than 3 questions.',
  '5. Derive every question from the first-round answers:',
  '   - drill deeper into concrete claims the candidate made;',
  '   - ask for clarification when an answer was vague, generic, or contradictory;',
  '   - verify the depth of technologies the candidate mentioned with concrete scenarios;',
  '   - where an answer was strong, ask a harder verification question.',
  '6. A single_choice question is a radio question with exactly one best answer and 3 or 4 options.',
  '7. A multi_choice question has 4 to 6 options and several of them can be correct; the candidate may select multiple options.',
  '8. Every option must carry an integer score from 0 to 4 that follows gradeGuide.scoringScale.',
  '9. Include plausible distractor options that sound confident but demonstrate shallow or incorrect understanding.',
  '10. Questions must be answerable without confidential or proprietary employer data.',
  '11. Write every question and every option in Persian (Farsi), addressed directly to the candidate.',
  '12. Do not include scores, scoring scale, or dimension codes inside the visible question or option text.',
  '13. Generate unique question ids matching the pattern F01 to F' + String(roundConfig.totalQuestions).padStart(2, '0') + '; ids must not repeat first-round ids.',
  '14. Return only the object required by the connected Structured Output Parser.',
  '',
  'Interview context:',
  JSON.stringify(interviewContext),
  '',
  'First-round questions and candidate answers:',
  JSON.stringify(answerRecords),
];

return [
  {
    json: {
      interviewContext,
      config,
      answerRecords,
      prompt: instructions.join(
        '\n'
      ),
    },
  },
];

