  typeCounts[type] += 1;

  dimensionCounts[dimensionCode] =
    (dimensionCounts[dimensionCode] ?? 0) + 1;

  const rawOptions = Array.isArray(question?.options)
    ? question.options
    : [];

  if (type === 'explanatory') {
    if (rawOptions.length > 0) {
      errors.push(
        `${id}: explanatory questions must not define options`
      );
      continue;
    }

    sanitizedQuestions.push({
      id,
      dimensionCode,
      type,
      questionText,
      options: [],
    });

    continue;
  }

  const minimumOptions = type === 'single_choice' ? 3 : 4;
  const maximumOptions = type === 'single_choice' ? 4 : 6;

  if (
    rawOptions.length < minimumOptions ||
    rawOptions.length > maximumOptions
  ) {
    errors.push(
      `${id}: ${type} requires ${minimumOptions} to ${maximumOptions} options`
    );
    continue;
  }

  const labels = new Set();
  const options = [];

  for (const option of rawOptions) {
    const label = String(option?.label ?? '').trim();

    if (!label) {
      errors.push(`${id}: option label is empty`);
      continue;
    }

    if (labels.has(label)) {
      errors.push(`${id}: duplicate option label`);
      continue;
    }

    labels.add(label);

    const score = Number(option?.score);

    if (!Number.isInteger(score) || score < 0 || score > 4) {
      errors.push(
        `${id}: option scores must be integers from 0 to 4`
      );
      continue;
    }

    options.push({ label, score });
  }

  if (options.length !== rawOptions.length) {
    continue;
  }

  const distinctScores = new Set(
    options.map((option) => option.score)
  );

  if (distinctScores.size < 2) {
    errors.push(
      `${id}: options must contain at least two distinct scores`
    );
    continue;
  }

  sanitizedQuestions.push({
    id,
    dimensionCode,
    type,
    questionText,
    options,
  });
}

if (sanitizedQuestions.length !== expected.total) {
  errors.push(
    `only ${sanitizedQuestions.length} of ${expected.total} questions survived validation`
  );
}

for (const type of Object.keys(typeCounts)) {
  if (typeCounts[type] !== expected[type]) {
    errors.push(
      `expected exactly ${expected[type]} ${type} questions, received ${typeCounts[type]}`
    );
  }
}

for (const dimensionCode of dimensionCodes) {
  const count = dimensionCounts[dimensionCode] ?? 0;

  if (count < 1 || count > 3) {
    errors.push(
      `${dimensionCode}: received ${count} follow-up questions, expected between 1 and 3`
    );
  }
}

if (errors.length > 0) {
  throw new Error(`INVALID_INTERVIEW_PLAN: ${errors.join("; ")}`);
}

const formFields = sanitizedQuestions.map(
  (question, index) => {
    const fieldLabel =
      `${index + 1}. ${question.questionText}`;

    if (question.type === 'explanatory') {
      return {
        fieldLabel,
        fieldName: `q_${question.id}`,
        fieldType: 'textarea',
        placeholder: 'پاسخ خود را همین‌جا بنویسید…',
        requiredField: true,
      };
    }

    return {
      fieldLabel,
      fieldName: `q_${question.id}`,
      fieldType: question.type === 'multi_choice' ? 'checkbox' : 'radio',
      fieldOptions: {
        values: question.options.map(
          (option) => ({ option: option.label })
        ),
      },
      requiredField: true,
    };
  }
);

const candidateName =
  interviewContext.candidate.fullName;

return [
  {
    json: {
      interviewContext,

      questionPlan: {
        schemaVersion: '1.0',
        round: 'followUp',
        title: String(
          questionPlan.interviewPlanTitle ?? 'TalentAI Follow-up Interview'
        ).trim(),
        questions: sanitizedQuestions,
        generationWarnings: Array.isArray(
          questionPlan.generationWarnings
        )
          ? questionPlan.generationWarnings.map(String)
          : [],
      },

      formFields,

      followUpFormTitle: 'مصاحبه فنی TalentAI — مرحله تکمیلی',

      followUpFormDescription:
        `${candidateName} عزیز، بر پایه پاسخ‌های مرحله اول، ${expected.total} سؤال تکمیلی برای شما طراحی شده است.` +
        ` این مجموعه شامل ${expected.single_choice} سؤال چندگزینه‌ای تک‌انتخابی، ${expected.multi_choice} سؤال چندگزینه‌ای چندانتخابی و ${expected.explanatory} سؤال تشریحی است.` +
        ' لطفاً مشخص و بر پایه تجربه واقعی خود پاسخ دهید.',
    },
  },
];

const formAnswers = $input.first().json;

const planContext =
  $('Validate Follow-up Questions').first().json;

const interviewContext =
  planContext.interviewContext;

const questionPlan =
  planContext.questionPlan;

const errors = [];
const answerRecords = [];

const toAnswerList = (value) => {
  if (Array.isArray(value)) {
    return value.map((item) => String(item ?? '').trim()).filter(Boolean);
  }

  const text = String(value ?? '').trim();
  return text ? [text] : [];
};

for (const question of questionPlan.questions) {
  const answerList = toAnswerList(formAnswers[`q_${question.id}`]);

  if (answerList.length === 0) {
    errors.push(`${question.id}: answer is empty`);
    continue;
  }

  if (question.type === 'explanatory') {
    answerRecords.push({
      round: 'followUp',
      id: question.id,
      dimensionCode: question.dimensionCode,
      type: question.type,
      questionText: question.questionText,
      answerLabels: [],
      answerText: answerList.join('\n'),
      mcqScore: null,
      llmScore: null,
      llmRationale: '',
      finalScore: null,
    });

    continue;
  }

  const unknownOption = answerList.find(
    (label) => !question.options.some((option) => option.label === label)
  );

  if (unknownOption !== undefined) {
    errors.push(
      `${question.id}: submitted option does not match the questionnaire`
    );
    continue;
  }

  if (question.type === 'single_choice' && answerList.length > 1) {
    errors.push(`${question.id}: only one option can be selected`);
    continue;
  }

  const selectedScores = answerList.map(
    (label) =>
      question.options.find((option) => option.label === label).score
  );

  const mcqScore =
    question.type === 'single_choice'
      ? selectedScores[0]
      : Math.round(
          (selectedScores.reduce(
            (total, score) => total + score,
            0
          ) /
            selectedScores.length) *
            100
        ) / 100;

  answerRecords.push({
    round: 'followUp',
    id: question.id,
    dimensionCode: question.dimensionCode,
    type: question.type,
    questionText: question.questionText,
    answerLabels: answerList,
    answerText: '',
    mcqScore,
    llmScore: null,
    llmRationale: '',
    finalScore: mcqScore,
  });
}

if (errors.length > 0) {
  throw new Error(`INVALID_INTERVIEW_ANSWERS: ${errors.join("; ")}`);
}

return [
  {
    json: {
      interviewContext,
      answerRecords,
    },
  },
];

const roundTwoContext = $input.first().json;

const roundOneRecords =
  $('Normalize Interview Answers').first().json.answerRecords;

const answerRecords = [
  ...roundOneRecords,
  ...roundTwoContext.answerRecords,
];

const interviewContext =
  roundTwoContext.interviewContext;

const scoringScale =
  interviewContext.gradeGuide.scoringScale;

const explanatoryItems = answerRecords
  .filter((record) => record.type === 'explanatory')
  .map((record) => ({
    round: record.round,
    id: record.id,
    dimensionCode: record.dimensionCode,
    questionText: record.questionText,
    answer: record.answerText,
  }));

if (explanatoryItems.length === 0) {
  throw new Error('NO_EXPLANATORY_ANSWERS: nothing to score');
}

const instructions = [
  'You are the interview-evaluator component of TalentAI.',
  '',
  'Your only responsibility is to score the explanatory interview answers of the candidate.',
  'Single-choice and multi-choice answers are scored deterministically elsewhere; you must not score them.',
  'You must not decide the final grade.',
  'You must not calculate the overall score.',
  '',
  'Rules:',
  '1. Score every supplied explanatory answer exactly once using its exact round and id.',
  '2. Apply the scoringScale semantics: 0 no usable evidence, 1 limited or vague,',
  '   2 practical and concrete, 3 advanced depth with explicit trade-offs or troubleshooting,',
  '   4 leadership-level depth or cross-cutting ownership.',
  '3. Score only what the answer itself demonstrates. Do not give credit for claims that the answer does not support.',
  '4. Generic, evasive, contradictory, or copied-sounding answers must receive score 0 or 1.',
  '5. Specific first-hand experience with concrete detail must receive at least 2.',
  '6. The follow-up round was designed from the first-round answers: if a follow-up answer stays vague while the first-round claim was strong, score it low and add a warning.',
  '7. If answers from the two rounds contradict each other, score each answer on its own merit and add a warning.',
  '8. Every score requires a short rationale in Persian.',
  '9. Return interviewSummary as a short Persian (Farsi) paragraph summarizing the interview quality across dimensions.',
  '10. Return only the object required by the connected Structured Output Parser.',
  '',
  'Scoring scale:',
  JSON.stringify(scoringScale),
  '',
  'Resume grade context:',
  JSON.stringify({
    decision: interviewContext.resumeGrade.decision,
    overallScore: interviewContext.resumeGrade.overallScore,
    dimensions: interviewContext.resumeGrade.dimensions,
  }),
  '',
  'Explanatory answers to score:',
  JSON.stringify(explanatoryItems),
];

return [
  {
    json: {
      interviewContext,
      answerRecords,
      prompt: instructions.join(
        '\n'
      ),
    },
  },
];

